using System;using System.IO;using System.Diagnostics;
class RuntimeProbe {static void Main(){string text;try {if(Type.GetType("Mono.Runtime")!=null)throw new Exception("Mono runtime");bool native=false;foreach(ProcessModule m in Process.GetCurrentProcess().Modules){if(m.ModuleName.Equals("clr.dll",StringComparison.OrdinalIgnoreCase)&&m.FileName.IndexOf("Microsoft.NET",StringComparison.OrdinalIgnoreCase)>=0)native=true;}if(!native)throw new Exception("Native CLR not loaded");text="NATIVE_CLR_OK\n"+Environment.Version;}catch(Exception e){text=e.ToString();}File.WriteAllText(@"C:\amazing-compat\runtime-probe.txt",text);}}
